        self.history_file = history_file
        self._history = self._load_history()

    def _load_history(self) -> List[Dict]:
        if os.path.exists(self.history_file):
            try:
                with open(self.history_file, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return []
        return []

    def _save_history(self) -> None:
        with open(self.history_file, 'w') as f:
            json.dump(self._history, f)

    def _validate_and_calc(self, a: Union[float, str], b: Union[float, str], op: str) -> Decimal:
        try:
            val_a = Decimal(str(a))
            val_b = Decimal(str(b))
        except (InvalidOperation, ValueError, TypeError):
            raise TypeError("Inputs must be valid numbers")

        if op == 'add':
            res = val_a + val_b
        elif op == 'subtract':
            res = val_a - val_b
        elif op == 'multiply':
            res = val_a * val_b
        elif op == 'divide':
            if val_b == 0:
                raise ValueError("Cannot divide by zero")
            res = val_a / val_b

        self._history.append({"operation": op, "args": (float(val_a), float(val_b)), "result": float(res)})
        self._save_history()
        return res

