class Calculator:
    """
    Handles arithmetic operations and tracks calculation history.

    Attributes:
        _history (deque): A thread-safe, memory-bounded history of operations.
    """

    def __init__(self, max_history: int = 100):
        self._history = deque(maxlen=max_history)

    def __repr__(self) -> str:
        return f"Calculator(history_size={len(self._history)})"

    def _validate_inputs(self, *args: float) -> None:
        """Validates that all inputs are numeric."""
        for arg in args:
            if not isinstance(arg, (int, float)):
                raise TypeError(f"All inputs must be numeric, got {type(arg).__name__}")

    def _format_result(self, a: float, b: float, op: str, result: float) -> float:
        """Helper to format precision and store in history."""
        # Round to handle float precision issues like 0.1 + 0.2
        result = round(float(result), 10)
        self._history.append(f"{a} {op} {b} = {result}")
        return result

    def add(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        return self._format_result(a, b, "+", a + b)

    def subtract(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        return self._format_result(a, b, "-", a - b)

    def multiply(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        return self._format_result(a, b, "*", a * b)

    def divide(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        if b == 0:
            raise ValueError("Cannot divide by zero.")
        return self._format_result(a, b, "/", a / b)

